mapper.select:
SELECT COUNT(*)
FROM biz_task_activity activity
INNER JOIN biz_task task
    ON task.id = activity.task_id
    AND task.deleted_at = 0
    AND (
        task.creator_id = #{userId}
        OR task.owner_id = #{userId}
        OR task.assigner_id = #{userId}
        OR EXISTS (
            SELECT 1 FROM biz_delivery_task_allocation allocation
            WHERE allocation.task_id = task.id
              AND allocation.team_owner_id = #{userId}
              AND allocation.deleted_at = 0
        )
        OR EXISTS (
            SELECT 1 FROM biz_task_follow follow_state
            WHERE follow_state.task_id = task.id
              AND follow_state.user_id = #{userId}
              AND follow_state.deleted_at = 0
        )
    )
WHERE activity.deleted_at = 0

