mapper.update:
UPDATE biz_task SET status = 'PROCESSING', accepted_at = #{now},
    version = version + 1, updated_by = #{ownerId}
WHERE id = #{id} AND owner_id = #{ownerId} AND version = #{version}
  AND status = 'PENDING_CONFIRMATION' AND deleted_at = 0

UPDATE biz_task SET status = 'PENDING_ACCEPTANCE', version = version + 1, updated_by = #{ownerId}
WHERE id = #{id} AND owner_id = #{ownerId} AND version = #{version}
  AND status = 'PROCESSING' AND deleted_at = 0

UPDATE biz_task SET status = 'PROCESSING', assigner_id = #{assignerId}, assigner_name = #{assignerName},
    assigned_at = #{now}, version = version + 1, updated_by = #{assignerId}
WHERE id = #{id} AND owner_id = #{ownerId} AND version = #{version}
  AND task_type = 'DELIVERY' AND status = 'PENDING_ASSIGNMENT' AND deleted_at = 0

UPDATE biz_task SET status = 'COMPLETED', completed_at = #{now}, version = version + 1, updated_by = #{ownerId}
WHERE id = #{id} AND owner_id = #{ownerId} AND version = #{version}
  AND task_type = 'DELIVERY' AND status = 'PENDING_ACCEPTANCE' AND deleted_at = 0

UPDATE biz_task SET status = 'PROCESSING', completed_at = NULL, version = version + 1, updated_by = #{ownerId}
WHERE id = #{id} AND owner_id = #{ownerId} AND version = #{version}
  AND task_type = 'DELIVERY' AND status = 'PENDING_ACCEPTANCE' AND deleted_at = 0

UPDATE biz_task SET status = 'COMPLETED', completed_at = #{now},
    version = version + 1, updated_by = #{creatorId}
WHERE id = #{id} AND creator_id = #{creatorId} AND version = #{version}
  AND status = 'PENDING_ACCEPTANCE' AND deleted_at = 0

UPDATE biz_task SET status = 'PROCESSING', completed_at = NULL,
    version = version + 1, updated_by = #{creatorId}
WHERE id = #{id} AND creator_id = #{creatorId} AND version = #{version}
  AND status = 'PENDING_ACCEPTANCE' AND deleted_at = 0

UPDATE biz_task SET status = 'WITHDRAWN', owner_id = NULL, owner_name = NULL,
    withdrawn_at = #{now}, withdraw_reason = #{reason},
    version = version + 1, updated_by = #{creatorId}
WHERE id = #{id} AND creator_id = #{creatorId} AND version = #{version}
  AND (status = 'PENDING_CONFIRMATION' OR (task_type = 'MATERIAL' AND status = 'PENDING_ASSIGNMENT')) AND deleted_at = 0

UPDATE biz_task SET status = 'REJECTED', rejected_at = #{now}, rejected_by = #{ownerId},
    rejection_reason = #{reason}, version = version + 1, updated_by = #{ownerId}
WHERE id = #{id} AND owner_id = #{ownerId} AND version = #{version}
  AND (
      status = 'PENDING_CONFIRMATION'
      OR (task_type = 'DELIVERY' AND status = 'PENDING_ASSIGNMENT')
  )
  AND deleted_at = 0
